def slug(s):
 return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()).strip('-')

BASE='''Generate a refined photographic storyboard contact sheet for an original naturalistic advertisement. EXACTLY FOUR equal portrait photographs in a 2 by 2 grid, order top-left, top-right, bottom-left, bottom-right. All four panels completely filled, edge-to-edge, with NO gutters, NO borders, NO text, NO letters, NO logos, NO captions, NO watermarks. Whole sheet portrait 2:3; each panel also 2:3. Images will be separated precisely at midpoints. Rich authentic human-shot smartphone aesthetics: natural light, moderate soft contrast, slightly lifted blacks but NO gray veil, honest material texture, normal human skin and believable anatomy, accurate product colors, subtle optical depth. Not glossy CGI, not stock-ad posing, not plain flat graphics, not a slideshow of identical compositions. Show actual physical actions and varied motivated framing. One coherent fictional product, same construction and exact color across all four frames, same adult characters with recognizable unchanged identities. Preserve natural body proportions and realistic garment fitting. No invented numbers or readable label data. All products, people and places are fictional demonstration examples; NOT real testimonial or performance proof. Environments should feel lived-in yet thoughtfully composed; layered foreground and background; beautiful but credible light. Avoid repeating the identical room, model or palette across unrelated concepts. Do not show words in this image: final subtitles and call-to-action are added later as editable text. Brazilian everyday context. Direction follows below in Portuguese.\n'''

pilots={
'Do gesto à assinatura':'01-joias.png','A casa começa antes da porta':'02-capachos.png','Antes da assinatura, uma conversa':'03-advocacia.png','Uma peça, o seu dia':'04-moda-feminina.png','A pausa cabe na bolsa':'05-barras.png','O som que muda a manhã':'06-cereal.png'}
jobs=[]
for group,label,rows in GROUPS:
 for i,(name,framework,look,beats,hook,benefit,objection,cta,sound) in enumerate(rows):
  frames=beats.split(';');assert len(frames)==4
  sid='natural-'+group+'-'+slug(name)
  j=dict(id=sid,name=name,family='ads-'+group,familyName=label,framework=framework,look=look,beats=frames,hook=hook,benefit=benefit,objection=objection,cta=cta,sound=sound,heroIndex=1,pilot=pilots.get(name),targetDurationRange=[30,45])
  j['prompt']=BASE+'CONCEITO: '+name+'. AMBIENTE E PRODUTO: '+look+'\n'+'\n'.join(f'QUADRO {n+1}: {b}.' for n,b in enumerate(frames))+'\nUse genuinely different camera distances per beat, beautiful and legible details, action and consequence. No graphic template. End on a context or product composition suitable for an editable CTA overlay.'
  jobs.append(j)
assert len(jobs)==60 and len({j['id'] for j in jobs})==60
(OUT/'concepts.json').write_text(json.dumps(jobs,ensure_ascii=False,indent=2)+'\n')
print('60 authored concepts; 6 approved pilot boards, 54 new boards to generate')
